sys_script_include.script:
ButtonUpdateScriptInclude.prototype.updateButton = function(buttonName, newValue) {
    var gr = new GlideRecord('u_marks_us_complete'); // Table name
    gr.addQuery('u_button_label', buttonName); // Ensure correct field for lookup
    gr.query();
	var newStatus = newValue ? 'Complete' : 'Incomplete'
    if (gr.next()) {
        gr.setValue('u_read_flag', newValue); // Update the relevant field
        gr.setValue('u_status', newStatus); // Update the relevant field
        gr.update();
        return { status: 'success', message: `Button ${buttonName} updated successfully.` };
    } else {
        return { status: 'error', message: `Button ${buttonName} not found.` };
    }
};
